{
  "意图": "在夜间，利用直射闪光灯摄影技术，为一名年轻女性打造出一幅极度理想化的、符合“抖音美学”风格的肖像。在天气晴朗的情况下，营造出高对比度、朦胧且富有艺术感的视觉效果。",
  "构图": {
    "宽高比": "9:16",
    "拍摄方式": "极近距离的自拍，构图比标准肖像更紧凑，裁剪掉额头的上部，以突出眼睛和嘴唇。主体位于画面中心，目光直视镜头。",
    "风格特点": "采用闪光灯摄影技术，结合数字网红的审美风格和柔和的虚化效果，呈现真实的画面感。"
  },
  "主体特征": {
    "身份": "一名约20岁的亚洲年轻女性，拥有超对称的、宛如玩偶般的面部特征，符合“兔舌”（嘴角微微上扬）和“狗狗眼”（眼睛圆润有神）的审美标准。",
    "皮肤": "肤色呈淡雅的冷色调，表面毫无纹理。皮肤在闪光灯照射下呈现出“糯米肌”或“玻璃肌”的效果，显得柔软且半透明。T区（额头和下巴）的亮度较高。",
    "眼睛": "眼睛大而圆，外眼角略微下垂（典型的“狗狗眼”）。眼下的脂肪纹被刻意突出，以增添年轻感。虹膜呈柔和的棕色，瞳孔直径较大。睫毛采用“韩剧风格”或“偶像风格”进行修饰：睫毛根部浓密，呈垂直排列，之间有间隔，而非传统的一片浓密。",
    "鼻子": "鼻子小巧，鼻梁较低，鼻尖圆润。光线处理使得鼻孔的轮廓几乎看不见，使鼻子看起来精致而低调。",
    "嘴唇": "嘴唇呈心形，采用了“渐变唇妆”技术。嘴唇中央部分为饱和的亮粉色，向外逐渐过渡为模糊的淡裸色。唇部质地柔软且富有水分。",
    "头发": "头发长而丝滑，呈纯黑色，自然下垂。在没有雪的情况下，头发显得干爽、顺滑，略微披在耳后或贴合面部轮廓，反射出白色的光泽。",
    "着装": "穿着简约大方，适合轻松愉悦的夜晚场合。"
  },
  "环境设定": {
    "地点": "城市夜晚环境。",
    "天气": "夜晚天气晴朗、宁静且美丽，空气清新，没有降水或雾气。",
    "背景": "背景为深黑色的阴影，远处城市灯光（路灯、霓虹灯）投射出柔和的圆形光晕。背景颜色比主体深得多，确保脸部成为唯一的焦点。"
  },
  "光线效果": {
    "光源类型": "直射的相机闪光灯或高强度的屏幕光源。",
    "光线质量": "光线坚硬但具有修饰效果，能够拉平面部轮廓，消除眼睛和鼻子下的阴影。这种效果常见于高端社交媒体的自拍中，使画面具有二维的、插画般的质感。",
    "对比度": "面部被明亮光线照亮，与周围漆黑的环境形成鲜明对比。",
    "特殊光效": "瞳孔中央因闪光灯照射而出现清晰的小亮点。"
  },
  "摄影设备": {
    "传感器类型": "模拟智能手机主摄像头。",
    "镜头规格": "24毫米广角镜头。这种焦距会略微夸大眼睛的大小，同时缩小鼻子和脸部的宽度，从而营造出“婴儿脸”的视觉效果。",
    "光圈值": "f/1.8至f/2.2，使眼睛和嘴唇的细节极为清晰，同时让耳朵和背景部分迅速变得模糊。",
    "对焦方式": "重点对焦睫毛和虹膜的纹理。"
  },
  "注意事项": {
    "禁止出现的元素": "没有雪、雨、湿漉漉的头发、男性化的下颌线条、皮肤纹理、毛孔、明显的轮廓修饰、西式妆容风格、太阳镜，以及手部靠近脸部的画面。",
    "风格限制": "不允许出现电影般的戏剧性阴影（必须使用平光效果）；不允许使用温暖的复古色调；禁止使用绘画或插画风格的处理。"
}

